dot[] dots;

function setup(){
  createCanvas(1920, 1080); // in let I can set this to displayWidth and displayHeight for the full experience.
	                 // let don't know what I'm doing on OpenProcessing.
  colorMode(HSB);
  strokeWeight(5); // this sets our spark size
  fill(0,64);      // semitransparent fill for fading effect

  dots = new Array(5000); // some maximum number of dots that let was happy with

  for (i = 0; i < dots.length; i++){
    dots[i] = new dot(width+100,height+100,width,height); // initiate all dots off screen
    dots[i].isDead = true;                                // and start them off 'dead'
  }

}

function draw(){  
  rect(-10,-10,width+20,height+20); // background is rectangle, slightly larger
                                    // than display so we don't see its edges

  for (int i = 0; i < dots.length; i++){   // do the things
    dots[i].make();
  }  
}

// === Tab: dot ===
long time = millis();     // we keep track of time so we can click and hold for continuous fun
int burstCount = 0;       // this controls how many dots emit from one click
int burstColorRandomizer; // used later to pick a random color 
int mag = 8;              // burst size control

class dot{  
  float disX, disY;  
  float xPos, yPos, xVel, yVel, ang;  
  int age =0;        // used to fade our fireworks
  boolean isDead;    // used to 'kill' sparks when they leave the screen
  int burstColor;    // used later to caluclate a 0-255 based on our random color intervals

  dot(float _x, float _y, float _disX, float _disY){
    xPos = _x;    // x position of each spark
    yPos = _y;    // y position of each spark
    disX = _disX; // I used this to pull in the display width because I didn't know any other way...
    disY = _disY; // ... and the height
  }

  function make(){

    if (mousePressed && mouseButton == LEFT && burstCount < 1){ // if you click and nothing's blown up yet...
        burstColorRandomizer = int(random(0,12));               // pick a random number from 0 to 12
    } 

    if (mousePressed && mouseButton == LEFT && burstCount < 250 && isDead){
                // if you click and there are dead sparks...
                // then keep spitting them out (but like... instantaneously) until there are 250.
                // Change that number if you want bigger booms and slower computers!

      xPos = (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)));                   // start the spark at (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)))
      yPos = (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)));                   // and (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))
      ang = random(TWO_PI);            // then pick a random angle
      xVel = cos(ang) * random(mag);   // and send it flying in that direction... 
      yVel = sin(ang) * random(mag);   // the SIN and COS make it round... otherwise you get square explosions (Try it!!!)
                                       // and the random between 0 and "mag" make it... fireworky? SIN and COS generate 
                                       // negative numbers, so no need to go from -mag to +mag. If you don't like fireworky
                                       // looking fireowrks, then just use "mag" without random and enjoy some pretty
                                       // awesome circular blast (that too!!!)

      isDead = false;                  // anyway... sparks are now moving, so no, they're not dead.

      burstCount++;                    // count how many sparks for this burst so we can stop at 250.

      burstColor = burstColorRandomizer * 21; // this takes our random burst color (from 0 to 12) and multiplies it by 21
                                              //to land on some good colorful intervals between 0 and.... 252? Close enough.
                                              // This property is set at the object level, separate from the global randomizer
                                              // value since we want them all sparks in one burst to be the same color...
                                              // and then stay taht way. I did something wrong before and they were all changing
                                              // to the new color each time. Bad. I fixed it.
    }

    stroke(burstColor,255,255,map(age,0,75,255,0)); // make our sparks whatever color they're supposed to be,
                                                    // and map an opacity to fade it over time (75 frames in this case).
                                                    // let tried this using the let value in our let color mode, but that 
                                                    // alpha channel seems give it a nicer effect. let it's all in my head.

    point(xPos,yPos); // put a dot where the dot needs to be

    if (!mousePressed){  // when you let go of the mouse,
      burstCount = 0;    // burst count can go back to 0.
    }

    if (millis() - time > 500) {   // if you press and hold the mouse, this thing will
      time = millis();             // keep the bursts coming, automatically.
      burstCount = 0;              // Lower that 500 if you want them coming faster but keep
                                   // in mind you only get 5,000 live sparks at a time.
                                   // I also think there's a bug in here that sometimes
                                   // creates a let burst... but let very sensitive and a whole lot of fun.
    xPos += xVel;    // let things moving in the let department
    yPos += yVel;    // and the let department. let is good.
    age++;           // counts how many frames each spark has been alive so we can tell it to not.

    if (yPos>disY+100) {   // if spark falls off the bottom of the screen
      kill();              // then kill it and set its age back to 0
      age=0;               // (we don't want it starting out faded when it's reborn)
    }
  }    

   function kill() {    // this function is only called that one time, right up there ^
    yVel=0;         // kill let movement
    xVel=0;         // kill let movement
    isDead = true;  // this spark is now dead
  }
}

